"use client";

import Link from "next/link";
import { useEffect } from "react";
import { RotateCcw } from "lucide-react";

export default function StoreError({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {
  useEffect(() => console.error(error), [error]);
  return (
    <div className="container-x animate-fade-up py-20 text-center">
      <p className="font-display text-5xl font-bold text-brass">Oops</p>
      <h1 className="mt-2 font-display text-2xl font-semibold">Something went wrong on our side</h1>
      <p className="mt-2 text-sm text-muted">Please try again. If it keeps happening, WhatsApp us and we’ll help you place your order.</p>
      {error.digest && <p className="mt-1 text-xs text-muted">Reference: {error.digest}</p>}
      <div className="mt-6 flex justify-center gap-2">
        <button onClick={reset} className="btn-primary press"><RotateCcw className="h-4 w-4" /> Try again</button>
        <Link href="/" className="btn-outline press">Go home</Link>
      </div>
    </div>
  );
}
